action.command:
cd /workspace && cat > /tmp/setpw.php <<'PHP'
<?php
$pdo = new PDO('mysql:host=db;dbname=db', 'db', 'db');
$hash = password_hash('Test1234', PASSWORD_BCRYPT);
$st = $pdo->prepare('UPDATE user SET password=:p WHERE id=1');
$st->execute([':p' => $hash]);
echo 'updated rows: ' . $st->rowCount() . PHP_EOL;
file_put_contents('/tmp/newpw.txt', $hash);
echo "new hash written\n";
PHP
cp /tmp/setpw.php /workspace/setpw_tmp.php && chown dev:dev /workspace/setpw_tmp.php && su - dev -c 'cd /workspace && export PATH=$HOME/.local/bin:$PATH && ddev exec php setpw_tmp.php' 2>&1 | grep -v Xdebug

